import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])

    answers = []
    index = 2
    for _ in range(n):
        sign = data[index][0]
        ai = int(data[index][1:])
        answers.append((sign, ai))
        index += 1

    # Create a list to store the count of truthful statements for each suspect
    truth_count = [0] * (n + 1)

    # Count the number of truthful statements for each suspect
    for i in range(n):
        sign, ai = answers[i]
        if sign == '+':
            truth_count[ai] += 1
        else:
            truth_count[ai] -= 1

    # Determine the suspects who could be the criminal
    possible_criminals = []
    for i in range(1, n + 1):
        if truth_count[i] == m:
            possible_criminals.append(i)

    # Determine the truthfulness of each suspect
    result = []
    for i in range(1, n + 1):
        if i in possible_criminals:
            result.append("Truth")
        elif any(truth_count[j] == m - 1 for j in range(1, n + 1) if j != i):
            result.append("Lie")
        else:
            result.append("Not defined")

    # Print the results
    for r in result:
        print(r)

if __name__ == "__main__":
    main()
